package br.com.onda;
import android.app.*;
import android.content.*;
import android.widget.*;
import java.lang.reflect.*;
import java.util.*;
import java.io.*;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class YoutubeRecoveryTest {
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void field(Object o,String n,Object value)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,value);}
 @Test public void verificationOptionsOpenOfficialPageAndKeepPlaylistSelection()throws Exception{Instrumentation ins=getInstrumentation();Context c=ins.getTargetContext();String old=c.getSharedPreferences(DownloadHistory.PREF,0).getString("data",null),status=c.getSharedPreferences("downloads",0).getString("status",null);boolean hadBusy=c.getSharedPreferences("downloads",0).contains("busy"),busy=c.getSharedPreferences("downloads",0).getBoolean("busy",false);c.getSharedPreferences(DownloadHistory.PREF,0).edit().remove("data").commit();Activity activity=ins.startActivitySync(new Intent(c,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Intent[] opened={null};Instrumentation.ActivityMonitor monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent intent){if(intent.getComponent()!=null&&intent.getComponent().getClassName().equals(YouTubeActivity.class.getName())){opened[0]=intent;return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(monitor);try{ins.runOnMainSync(()->{try{List<YoutubeDownloads.Entry> entries=Arrays.asList(new YoutubeDownloads.Entry("A","https://youtu.be/i7j0bw5TonI"),new YoutubeDownloads.Entry("B","https://youtu.be/aqz-KE-bpKQ"));PlaylistSelection selected=new PlaylistSelection(entries);selected.set(1,true);field(activity,"selectionState",selected);field(activity,"playlistItems",selected.items);field(activity,"source","https://www.youtube.com/playlist?list=RDi7j0bw5TonI");Method message=DownloadsActivity.class.getDeclaredMethod("message",String.class);message.setAccessible(true);message.invoke(activity,"O YouTube exigiu confirmação de que você não é um robô.");Button button=(Button)field(activity,"youtubeRecovery");assertEquals(android.view.View.VISIBLE,button.getVisibility());button.performClick();AlertDialog dialog=(AlertDialog)field(activity,"recoveryDialog");assertNotNull(dialog.getListView());assertTrue(dialog.getListView().isShown());dialog.getListView().performItemClick(null,0,0);assertNotNull(opened[0]);assertEquals("https://m.youtube.com/playlist?list=RDi7j0bw5TonI",opened[0].getStringExtra(YouTubeFavorites.EXTRA));assertEquals(1,selected.count());button.performClick();((AlertDialog)field(activity,"recoveryDialog")).getListView().performItemClick(null,2,2);PlaylistPicker picker=(PlaylistPicker)field(activity,"picker");assertNotNull(picker);assertEquals(1,picker.selection.count());assertTrue(picker.selection.contains(1));}catch(Exception e){throw new RuntimeException(e);}});}finally{ins.removeMonitor(monitor);ins.runOnMainSync(activity::finish);ins.waitForIdleSync();SharedPreferences.Editor e=c.getSharedPreferences(DownloadHistory.PREF,0).edit();if(old==null)e.remove("data");else e.putString("data",old);e.commit();e=c.getSharedPreferences("downloads",0).edit();if(status==null)e.remove("status");else e.putString("status",status);if(hadBusy)e.putBoolean("busy",busy);else e.remove("busy");e.commit();}}
 @Test public void userMixAvailabilityIsReportedWithoutPretendingVerificationWasBypassed()throws Exception{Context c=getInstrumentation().getTargetContext();JSONObject report=new JSONObject().put("source","https://www.youtube.com/playlist?list=RDi7j0bw5TonI");try{YoutubeDownloads.Playlist playlist=YoutubeDownloads.playlist(report.getString("source"));report.put("loadedItems",playlist.items.size());YoutubeDownloads.Result result=YoutubeDownloads.inspect(playlist.items.get(0).url);report.put("availability","formats-found").put("formats",result.options.size());assertFalse(result.options.isEmpty());}catch(Exception e){String reason=DownloadFailure.describe("Consulta",e);report.put("availability",YoutubeVerification.required(reason)?"verification-required":"provider-unavailable").put("reason",reason);}try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-recovery-tests.json"))){out.write(report.toString(2).getBytes("UTF-8"));}}
}
